-- 044: Frentes estratégicos. EJECUCIÓN MANUAL DEL OWNER, nunca automática.
-- roadmap_items contiene tareas libres; no tiene el ciclo/historial de una iniciativa.
-- Un agregado JSONB mantiene hitos ordenados e historial atómicos, sin tablas de tareas.
begin;
create table if not exists public.hq_fronts (
 id uuid primary key default gen_random_uuid(),
 document jsonb not null,
 created_at timestamptz not null default now(),
 constraint hq_front_id check (document->>'id' = id::text),
 constraint hq_front_state check (document->>'estado' in ('BACKLOG','DISCOVERY','EN_DESARROLLO','VALIDACION','BLOQUEADO','CERRADO')),
 constraint hq_front_health check (document->>'salud' in ('EN_CURSO','ATENCION','BLOQUEADO')),
 constraint hq_front_priority check (document->>'prioridad' in ('P0','P1','P2')),
 constraint hq_front_document check (document ?& array['id','nombre','objetivo','estado','salud','prioridad','proxima_accion','updated_at','hitos','updates','cerrado_at']),
 constraint hq_front_next check (document->>'estado' = 'CERRADO' or length(trim(document->>'proxima_accion')) > 0),
 constraint hq_front_closed check ((document->>'estado' = 'CERRADO') = (document->>'cerrado_at' is not null)),
 constraint hq_front_arrays check (jsonb_typeof(document->'hitos') = 'array' and jsonb_typeof(document->'updates') = 'array')
);
alter table public.hq_fronts enable row level security;
revoke all on public.hq_fronts from anon, authenticated;
grant select, insert, update on public.hq_fronts to service_role;
insert into public.hq_fronts(id,document) values ('f0000000-0000-4000-8000-000000000001', '{"categoria":"ADS","estado":"EN_DESARROLLO","salud":"BLOQUEADO","prioridad":"P0","fase":"Meta + Google publicación real","proximo_hito":"Primera campaña real creada desde Respondo en Meta y Google","proxima_accion":"Resolver permisos Meta y repetir la creación de una campaña PAUSED desde Respondo.","bloqueo":"Según ADS_LIVE_V1_REPORT: Meta rechaza publicación por permisos; Google sin credenciales OAuth. Confirmar vigencia con el owner.","owner_action":"Conceder ads_management y Página en Meta; configurar OAuth de Google Ads.","fecha_objetivo":"","cerrado_at":null,"created_at":"2026-09-17T12:00:00.000Z","updated_at":"2026-09-17T12:00:00.000Z","hitos":[{"nombre":"Meta Read","completado_at":"2026-09-17T12:00:00.000Z"},{"nombre":"Meta Publish","completado_at":null},{"nombre":"Meta Live Test","completado_at":null},{"nombre":"Google Read","completado_at":null},{"nombre":"Google Publish","completado_at":null},{"nombre":"Google Live Test","completado_at":null}],"links":[{"label":"Informe Ads Live V1","reference":"respondo-portal/docs/ADS_LIVE_V1_REPORT.md"}],"updates":[{"fecha":"2026-09-17T12:00:00.000Z","autor":"Inicialización · misión owner","texto":"Registro inicial basado en la misión y referencias indicadas; no implica una nueva validación de producción. Fechas históricas de cierre no disponibles: se registra fecha de archivo."}],"nombre":"Ads Live V1","objetivo":"Dejar Meta Ads y Google Ads operativos de punta a punta.","id":"f0000000-0000-4000-8000-000000000001"}'::jsonb) on conflict (id) do nothing;
